\label{lem:cavg}
Let \((\mathcal X,d)\) be a finite metric space, let \(\nu_0,\nu_1\) be
probability measures on \(\mathcal X\), and let \(A\ge0\),
\(\gamma\in[0,1/8]\).
Suppose \(h,\eta,\eta'\colon\mathcal X\to\mathbb{C}\) satisfy
\begin{align}
  |h(\xi)-h(\xi')|&\le A\,d(\xi,\xi'),\label{eq:cavg-lip}\\
  \max_{\xi,\xi'}|h(\xi)-h(\xi')|&\le1/8,\label{eq:cavg-range}\\
  \|\eta\|_\infty,\ \|\eta'\|_\infty&\le\gamma,\label{eq:cavg-eta}
\end{align}
where \(\|f\|_\infty=\max_\xi|f(\xi)|\).  Then the averages \(\operatorname{\mathbb{E}}_{\nu_0}[e^{h+\eta}]\) and
\(\operatorname{\mathbb{E}}_{\nu_1}[e^{h+\eta'}]\) are nonzero
and, with \(\operatorname{Log}\) of their ratio taken as the continuous branch that
vanishes at \(h=\eta=\eta'=0\) on the convex set of triples
\((h,\eta,\eta')\) satisfying
\eqref{eq:cavg-lip}--\eqref{eq:cavg-eta},
\begin{equation}\label{eq:cavg}
  \left|\operatorname{Log}\frac{\operatorname{\mathbb{E}}_{\nu_0}[e^{h+\eta}]}{\operatorname{\mathbb{E}}_{\nu_1}[e^{h+\eta'}]}\right|
  \le2A\,W_{1,d}(\nu_0,\nu_1)+4\gamma.
\end{equation}

\label{lem:potts-hard-comparison}
Assume \(q\ge\Delta+1\) and put \(H_*:=q^\Delta\).  For every
\(G\in\mathcal{G}_{\Delta}\), every pinning \(\tau\), every \(y\in V^\tau\), and all
colours \(a,b\),
\begin{equation}\label{eq:potts-hard-comparison}
  \widehat Z_{G}^{\tau^{y=a}}(0)
  \le H_*\widehat Z_{G}^{\tau^{y=b}}(0).
\end{equation}

\label{lem:active-rep}
If \(\sigma\sim\mu_{G,x}^{\tau}\) and \(A\) is sampled as above,
then \(\sigma\), conditional on \(A\), is uniform on \(\Omega_{F_A}\).

\label{prop:hard-one-step}
The updates admit a coupling \((X',Y')\), with
\(X'\sim\Phi_{F_X}(X,\cdot)\) and \(Y'\sim\Phi_{F_Y}(Y,\cdot)\), such
that
\begin{equation}\label{eq:conditional-hard-estimate}
  nq\,\operatorname{\mathbb{E}}[\operatorname{Ham}(X',Y')-1\mid\mathcal A]
  \le\frac{11}{6}\sum_c|N_c|-\ell.
\end{equation}

\label{lem:soft-contraction}
For \(G\in\mathcal{G}_{\Delta}\), a pinning \(\tau\), and \(x\in(0,1]\), put
\(t=1-x\) and \(n=|V^\tau|\ge1\).  Colourings \(X,Y\) at Hamming
distance one admit a coupling \((X',Y')\) of one step of
\(K_x^{G,\tau}\) satisfying
\begin{equation}\label{eq:soft-averaged-drift}
  nq\,\operatorname{\mathbb{E}}[\operatorname{Ham}(X',Y')-1]\le\frac{11}{6}t\Delta-q.
\end{equation}
In particular, if \(q>(11/6)t\Delta\), the soft kernel contracts Hamming
distance by the factor \(1-\kappa_x/n\), where
\begin{equation}\label{eq:soft-kappa}
  \kappa_x=\frac{q-(11/6)t\Delta}{q}>0.
\end{equation}

\label{prop:full-interval-hci}
Let \(q,\Delta\) be positive integers with \(\Delta\ge2\).  For every
\(G\in\mathcal{G}_{\Delta}\), every pinning \(\tau\), every \(r\in V^\tau\), all
\(a,b\in[q]\), and every \(x\in(0,1]\) satisfying
\(q>(11/6)(1-x)\Delta\),
\begin{equation}\label{eq:vigoda-master-ci}
  W_{1,\operatorname{Ham}}\!\left(
    \mu_{G,x}^{\tau^{r=a}},\mu_{G,x}^{\tau^{r=b}}
  \right)
  \le\frac{2(1-x)\Delta}{q-(11/6)(1-x)\Delta}.
\end{equation}
If \(q>11\Delta/6\), the bound \eqref{eq:vigoda-master-ci} also holds at
\(x=0\).
